<span class="line"><span style="color:#E06C75;">        expiry_epoch</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">$(</span><span style="color:#61AFEF;">date</span><span style="color:#D19A66;"> -d</span><span style="color:#98C379;"> &quot;</span><span style="color:#E06C75;">$expiry</span><span style="color:#98C379;">&quot;</span><span style="color:#98C379;"> +%s</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span><span style="color:#ABB2BF;"> || </span><span style="color:#61AFEF;">date</span><span style="color:#D19A66;"> -j</span><span style="color:#D19A66;"> -f</span><span style="color:#98C379;"> &quot;%b %d %T %Y %Z&quot;</span><span style="color:#98C379;"> &quot;</span><span style="color:#E06C75;">$expiry</span><span style="color:#98C379;">&quot;</span><span style="color:#98C379;"> +%s</span><span style="color:#ABB2BF;">)</span></span>
